## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/psoriasisLogic.ts`

```typescript
/**
 * Psoriasis Clinical Logic Engine
 *
 * Based on:
 * - AAD-NPF 2019/2026 Joint Guidelines of Care for Psoriasis with Biologics
 *   (PMID: 30772097)
 * - AAD-NPF 2026 Update: TYK2 inhibitors, IL-23 evolution, treat-to-target
 * - Translating 2019 AAD-NPF Guidelines to Clinical Practice (PMID: 31634385)
 * - PASI/BSA/DLQI severity framework (IPC criteria)
 */

export type PsoriasisSeverity = "mild" | "moderate" | "severe";
export type PsoriasisSubtype =
  | "plaque"
  | "guttate"
  | "pustular_localized"
  | "pustular_generalized"
  | "erythrodermic"
  | "inverse"
  | "nail"
  | "scalp";

export type SpecialSite = "scalp" | "nails" | "palmoplantar" | "intertriginous" | "genitalia" | "none";
export type PriorPsoriasisTreatment =
  | "none"
  | "topicals_only"
  | "topicals_and_phototherapy"
  | "prior_conventional_systemic"
  | "prior_tnf"
  | "prior_il17"
  | "prior_il23"
  | "prior_il12_23";

export interface PsoriasisInput {
  // Severity scoring
  bsaPercent: number; // 0-100
  dlqi: number; // 0-30 Dermatology Life Quality Index
  pgaScore: 0 | 1 | 2 | 3 | 4 | 5; // 0=clear, 5=very severe

  // Disease characteristics
  subtype: PsoriasisSubtype;
  specialSites: SpecialSite[];
  hasPsoriaticArthritis: boolean;
  hasNailInvolvement: boolean;

  // Prior treatment
  priorTreatment: PriorPsoriasisTreatment;

  // Comorbidities
  hasCardiovascularDisease: boolean; // affects TNF inhibitor choice
  hasInflammatoryBowelDisease: boolean; // avoid IL-17 inhibitors
  hasDemyelinatingDisease: boolean; // avoid TNF inhibitors
  hasActiveTuberculosis: boolean;
  hasChronicHBV: boolean;
  hasHepaticImpairment: boolean;
  hasMalignancyHistory: boolean;
  isImmunocompromised: boolean;
  isPregnant: boolean;
  isBreastfeeding: boolean;

  // Patient factors
  prefersOralTherapy: boolean;
  hasObesity: boolean; // BMI >30 — affects ustekinumab dosing and GLP-1 synergy
  hasMetabolicSyndrome: boolean;
}

export interface PsoriasisRecommendation {
  severity: PsoriasisSeverity;
  primaryRecommendation: string;
  treatmentPathway: string;
  firstLineAgents: string[];
  alternativeAgents: string[];
  agentsToAvoid: string[];
  specialSiteManagement: string[];
  psoriaticArthritisNotes: string[];
  monitoringPlan: string[];
  urgentFlags: string[];
  nextSteps: string[];
  treatToTargetGoal: string;
  evidenceLevel: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
  sharedDecisionPoints: string[];
}

function classifyPsoriasisSeverity(input: PsoriasisInput): PsoriasisSeverity {
  // Rule of Tens: BSA >10, PASI >10, or DLQI >10 = severe
  // Special sites always qualify for systemic therapy regardless of BSA
  const hasSpecialSite =
    input.specialSites.includes("palmoplantar") ||
    input.specialSites.includes("nails") ||
    input.specialSites.includes("genitalia") ||
    input.hasPsoriaticArthritis;

  if (input.subtype === "erythrodermic" || input.subtype === "pustular_generalized") {
    return "severe";
  }

  if (input.bsaPercent > 10 || input.dlqi > 10 || input.pgaScore >= 4) {
    return "severe";
  }

  if (input.bsaPercent >= 3 || input.dlqi >= 6 || input.pgaScore === 3 || hasSpecialSite) {
    return "moderate";
  }

  return "mild";
}

export function assessPsoriasis(input: PsoriasisInput): PsoriasisRecommendation {
  const severity = classifyPsoriasisSeverity(input);

  const urgentFlags: string[] = [];
  const firstLineAgents: string[] = [];
  const alternativeAgents: string[] = [];
  const agentsToAvoid: string[] = [];
  const specialSiteManagement: string[] = [];
  const psoriaticArthritisNotes: string[] = [];
  const nextSteps: string[] = [];
  const monitoringPlan: string[] = [];
  const sharedDecisionPoints: string[] = [];

  // Urgent flags
  if (input.subtype === "erythrodermic") {
    urgentFlags.push("URGENT: Erythrodermic psoriasis — hospitalization may be required; avoid abrupt withdrawal of systemic therapy; cyclosporine or infliximab for rapid control");
  }
  if (input.subtype === "pustular_generalized") {
    urgentFlags.push("URGENT: Generalized pustular psoriasis — systemic therapy required urgently; cyclosporine or infliximab; biologics (IL-17, IL-23) emerging as preferred");
  }
  if (input.hasActiveTuberculosis) {
    urgentFlags.push("ACTIVE TB: All biologics and JAK inhibitors contraindicated until TB fully treated; consult infectious disease");
  }
  if (input.hasChronicHBV) {
    urgentFlags.push("Chronic HBV: Antiviral prophylaxis required before initiating biologics; consult hepatology");
  }

  // Contraindications
  if (input.hasInflammatoryBowelDisease) {
    agentsToAvoid.push("IL-17 inhibitors (secukinumab, ixekizumab, bimekizumab, brodalumab) — may worsen IBD");
    agentsToAvoid.push("Brodalumab — IL-17RA blocker; avoid in IBD");
  }
  if (input.hasDemyelinatingDisease) {
    agentsToAvoid.push("TNF inhibitors (etanercept, adalimumab, infliximab, certolizumab) — contraindicated in demyelinating disease");
  }
  if (input.hasMalignancyHistory) {
    agentsToAvoid.push("TNF inhibitors — avoid in patients with recent malignancy history");
  }
  if (input.isPregnant) {
    agentsToAvoid.push("Acitretin — absolutely contraindicated in pregnancy (teratogenic)");
    agentsToAvoid.push("Methotrexate — contraindicated in pregnancy");
    agentsToAvoid.push("Most biologics — limited safety data; certolizumab has best pregnancy safety profile");
  }

  let primaryRecommendation = "";
  let treatmentPathway = "";
  let evidenceLevel = "";
  let treatToTargetGoal = "";

  if (severity === "mild") {
    primaryRecommendation = "Topical therapy — corticosteroids, vitamin D analogs, and non-steroidal topicals";
    treatmentPathway =
      "Step 1: Topical corticosteroids (mid-to-high potency for body; low potency for face/intertriginous). " +
      "Step 2: Vitamin D analogs (calcipotriene, calcitriol) — steroid-sparing; combine with TCS for additive effect. " +
      "Step 3: Fixed-dose calcipotriene + betamethasone dipropionate (Taclonex/Enstilar) — once-daily convenience. " +
      "Step 4: Tazarotene — retinoid; effective for plaques; irritating on sensitive skin. " +
      "Step 5: Roflumilast foam 0.3% (Zoryve) — for scalp and intertriginous areas. " +
      "Step 6: Tapinarof cream 1% — AhR agonist; approved for plaque psoriasis.";

    firstLineAgents.push("Calcipotriene + betamethasone dipropionate (Taclonex) — fixed-dose combination; once daily");
    firstLineAgents.push("Topical corticosteroids (class II-IV for body plaques)");
    firstLineAgents.push("Roflumilast foam 0.3% (Zoryve) — scalp and intertriginous; non-steroidal");
    firstLineAgents.push("Tapinarof cream 1% — plaque psoriasis; 'remittive effect' after stopping");
    firstLineAgents.push("Calcipotriene 0.005% cream/solution — vitamin D analog; steroid-sparing");

    treatToTargetGoal = "Clear or near-clear (BSA <1%) within 3 months";
    evidenceLevel = "Strong recommendation (AAD-NPF 2019/2026, Level A)";

  } else if (severity === "moderate") {
    primaryRecommendation = "Systemic therapy — biologic preferred over conventional systemic for moderate-severe plaque psoriasis";
    treatmentPathway =
      "Step 1: Topical therapy + phototherapy (narrowband UVB) if accessible. " +
      "Step 2: Conventional systemic: methotrexate (first-line non-biologic), apremilast (oral PDE-4i; no lab monitoring). " +
      "Step 3: Biologic therapy — IL-23 inhibitors preferred for sustained efficacy and safety profile. " +
      "Step 4: TYK2 inhibitor (deucravacitinib 6mg daily) — oral; biologic-level efficacy; no immunosuppression boxed warning. " +
      "Step 5: IL-17 inhibitors for rapid clearance (bimekizumab, secukinumab, ixekizumab). " +
      "Step 6: TNF inhibitors (adalimumab) — effective but lower efficacy vs IL-17/IL-23.";

    if (input.prefersOralTherapy) {
      firstLineAgents.push("Deucravacitinib 6mg daily — TYK2 inhibitor; oral; biologic-level PASI 75 rates; no boxed warning");
      firstLineAgents.push("Apremilast 30mg BID — oral PDE-4 inhibitor; no lab monitoring required; suitable for mild-moderate");
      firstLineAgents.push("Methotrexate 7.5-25mg weekly — conventional systemic; less effective than biologics");
    } else {
      firstLineAgents.push("Risankizumab (IL-23 p19) — Q12W maintenance; high PASI 90/100 rates; AAD-NPF 2026 preferred");
      firstLineAgents.push("Guselkumab (IL-23 p19) — Q8W; also approved for psoriatic arthritis");
      firstLineAgents.push("Tildrakizumab (IL-23 p19) — Q12W; effective for moderate-severe plaque");
      firstLineAgents.push("Bimekizumab (IL-17A/F) — highest PASI 90/100 rates; Q4W then Q8W");
      firstLineAgents.push("Secukinumab (IL-17A) — 300mg Q4W; rapid clearance");
      firstLineAgents.push("Ixekizumab (IL-17A) — Q4W then Q8W; effective for nails and PsA");
    }

    if (input.hasPsoriaticArthritis) {
      psoriaticArthritisNotes.push("PsA present: IL-17 inhibitors (secukinumab, ixekizumab) and IL-23 inhibitors (guselkumab, risankizumab) treat both skin and joints");
      psoriaticArthritisNotes.push("TNF inhibitors (adalimumab, certolizumab) — well-established for PsA; consider if IBD or CV disease present");
      psoriaticArthritisNotes.push("Deucravacitinib — approved for both plaque psoriasis and PsA");
      psoriaticArthritisNotes.push("Rheumatology co-management recommended for PsA");
    }

    treatToTargetGoal = "PASI 90 or BSA <1% within 3 months of starting new therapy (AAD-NPF treat-to-target)";
    evidenceLevel = "Strong recommendation (AAD-NPF 2019/2026, Level A)";

  } else {
    // Severe
    primaryRecommendation = "Biologic therapy — IL-23 or IL-17 inhibitors are preferred first-line for severe plaque psoriasis";
    treatmentPathway =
      "Step 1: IL-23 inhibitors (risankizumab, guselkumab, tildrakizumab) — preferred for sustained remission, Q12W maintenance. " +
      "Step 2: IL-17 inhibitors (bimekizumab, secukinumab, ixekizumab) — fastest clearance; preferred for palmoplantar/nail/PsA. " +
      "Step 3: TYK2 inhibitor (deucravacitinib) — oral option with biologic-level efficacy; no immunosuppression boxed warning. " +
      "Step 4: TNF inhibitors (adalimumab, infliximab, certolizumab) — effective; consider if CV disease or IBD present. " +
      "Step 5: Ustekinumab (IL-12/23) — less preferred vs IL-23 selective agents; approved ≥12 years. " +
      "Step 6: Cyclosporine — for rapid control of severe/erythrodermic; short-term only (≤1 year).";

    if (input.hasInflammatoryBowelDisease) {
      firstLineAgents.push("IL-23 inhibitors (risankizumab, guselkumab) — safe in IBD; preferred over IL-17");
      firstLineAgents.push("TNF inhibitors (adalimumab, infliximab) — treat both psoriasis and IBD");
    } else if (input.hasPsoriaticArthritis) {
      firstLineAgents.push("Bimekizumab (IL-17A/F) — highest skin clearance + PsA efficacy");
      firstLineAgents.push("Secukinumab (IL-17A) — established for both psoriasis and PsA");
      firstLineAgents.push("Guselkumab (IL-23 p19) — FDA approved for PsA + psoriasis");
    } else {
      firstLineAgents.push("Risankizumab (IL-23 p19) — highest PASI 90/100 rates; Q12W maintenance; preferred AAD-NPF 2026");
      firstLineAgents.push("Bimekizumab (IL-17A/F) — fastest clearance; Q4W loading then Q8W");
      firstLineAgents.push("Guselkumab (IL-23 p19) — Q8W; approved for PsA");
    }

    if (input.prefersOralTherapy) {
      firstLineAgents.push("Deucravacitinib 6mg daily — oral TYK2 inhibitor; PASI 75 rates comparable to adalimumab; no boxed warning");
      alternativeAgents.push("Apremilast — less effective for severe disease; use if biologic contraindicated");
    }

    alternativeAgents.push("Ustekinumab (IL-12/23) — less preferred vs selective IL-23 agents; approved ≥12 years");
    alternativeAgents.push("Adalimumab (TNF) — well-established; preferred if IBD or CV disease");
    alternativeAgents.push("Infliximab — fastest TNF response; IV infusion; for erythrodermic/pustular");

    if (input.subtype === "erythrodermic" || input.subtype === "pustular_generalized") {
      firstLineAgents.push("Cyclosporine 3-5mg/kg/day — rapid control; bridge to biologic");
      firstLineAgents.push("Infliximab 5mg/kg IV — fastest biologic response for erythrodermic/pustular");
    }

    treatToTargetGoal = "PASI 90 or BSA <1% within 3 months; reassess and switch if PASI 75 not achieved at 16 weeks";
    evidenceLevel = "Strong recommendation (AAD-NPF 2019/2026, Level A)";
  }

  // Special site management
  if (input.specialSites.includes("scalp")) {
    specialSiteManagement.push("Scalp: Roflumilast foam 0.3% (Zoryve) — non-steroidal; once daily; AAD 2026 preferred");
    specialSiteManagement.push("Scalp: Clobetasol propionate shampoo or foam — high-potency TCS for scalp");
    specialSiteManagement.push("Scalp: Calcipotriene + betamethasone dipropionate foam (Enstilar) — once daily");
  }
  if (input.specialSites.includes("nails")) {
    specialSiteManagement.push("Nails: IL-17 inhibitors (ixekizumab, secukinumab) most effective for nail psoriasis");
    specialSiteManagement.push("Nails: Intralesional triamcinolone — for isolated nail disease");
    specialSiteManagement.push("Nails: Tazarotene gel under occlusion — topical option");
  }
  if (input.specialSites.includes("palmoplantar")) {
    specialSiteManagement.push("Palmoplantar: IL-17 inhibitors (secukinumab, ixekizumab, bimekizumab) most effective");
    specialSiteManagement.push("Palmoplantar: Acitretin — consider for pustular palmoplantar; combine with PUVA");
    specialSiteManagement.push("Palmoplantar: High-potency TCS under occlusion for localized disease");
  }
  if (input.specialSites.includes("intertriginous") || input.specialSites.includes("genitalia")) {
    specialSiteManagement.push("Intertriginous/genital: Roflumilast foam 0.3% — non-steroidal; safe for sensitive areas");
    specialSiteManagement.push("Intertriginous/genital: Low-potency TCS (hydrocortisone 1-2.5%) — avoid high-potency");
    specialSiteManagement.push("Intertriginous/genital: Tacrolimus ointment 0.1% — off-label but effective");
  }

  // Obesity / metabolic syndrome
  if (input.hasObesity || input.hasMetabolicSyndrome) {
    sharedDecisionPoints.push("Obesity: GLP-1 receptor agonists (tirzepatide, semaglutide) may have immunometabolic synergy in psoriasis — emerging evidence");
    sharedDecisionPoints.push("Ustekinumab: weight-based dosing (>100kg: 90mg; ≤100kg: 45mg) — consider higher-efficacy agents in obese patients");
    sharedDecisionPoints.push("Weight loss improves psoriasis severity independently — lifestyle counseling recommended");
  }

  // Monitoring
  monitoringPlan.push("Reassess BSA, PGA, and DLQI at 3 months after initiating new therapy");
  monitoringPlan.push("Treat-to-target: switch therapy if PASI 75 not achieved at 16 weeks");
  monitoringPlan.push("Biologics: TB screening (IGRA/PPD), hepatitis B/C, CBC, LFTs at baseline");
  monitoringPlan.push("Methotrexate: LFTs, CBC, renal function every 4-8 weeks initially");
  monitoringPlan.push("Cyclosporine: BP, renal function, CBC every 2 weeks for first 3 months");
  monitoringPlan.push("Annual cardiovascular risk assessment — psoriasis is an independent CV risk factor");

  // Next steps
  nextSteps.push("Screen for psoriatic arthritis at every visit (PEST or PASE questionnaire)");
  nextSteps.push("Assess DLQI — if >10, qualifies for systemic therapy regardless of BSA");
  nextSteps.push("Dermatology referral if not responding to topicals or phototherapy");
  nextSteps.push("Counsel on cardiovascular risk — psoriasis associated with increased MACE risk");

  sharedDecisionPoints.push("Route of administration: oral (deucravacitinib, apremilast, methotrexate) vs SC injection (biologics) — patient preference");
  sharedDecisionPoints.push("Dosing frequency: Q12W (risankizumab) vs Q4-8W (IL-17 agents) — adherence consideration");
  sharedDecisionPoints.push("Prior authorization: biologics require documentation of topical failure and/or phototherapy failure");
  sharedDecisionPoints.push("Biosimilars available for adalimumab, etanercept, infliximab, ustekinumab — cost consideration");

  return {
    severity,
    primaryRecommendation,
    treatmentPathway,
    firstLineAgents,
    alternativeAgents,
    agentsToAvoid,
    specialSiteManagement,
    psoriaticArthritisNotes,
    monitoringPlan,
    urgentFlags,
    nextSteps,
    treatToTargetGoal,
    evidenceLevel,
    sharedDecisionPoints,
    references: [
      {
        citation: "Joint AAD-NPF Guidelines of Care for the Management and Treatment of Psoriasis with Biologics — Menter A et al., JAAD 2019",
        pmid: "30772097",
        url: "https://pubmed.ncbi.nlm.nih.gov/30772097/",
      },
      {
        citation: "Translating the 2019 AAD-NPF Guidelines of Care for Psoriasis with Biologics to Clinical Practice — Armstrong AW et al., JAAD 2020",
        pmid: "31634385",
        url: "https://pubmed.ncbi.nlm.nih.gov/31634385/",
      },
      {
        citation: "Deucravacitinib vs Placebo and Apremilast in Moderate-to-Severe Plaque Psoriasis — Armstrong AW et al., NEJM 2023",
        pmid: "36720134",
        url: "https://pubmed.ncbi.nlm.nih.gov/36720134/",
      },
      {
        citation: "Bimekizumab vs Secukinumab in Plaque Psoriasis — Reich K et al., NEJM 2021",
        pmid: "34161699",
        url: "https://pubmed.ncbi.nlm.nih.gov/34161699/",
      },
      {
        citation: "Risankizumab vs Ustekinumab for Moderate-to-Severe Plaque Psoriasis — Gordon KB et al., Lancet 2018",
        pmid: "29961678",
        url: "https://pubmed.ncbi.nlm.nih.gov/29961678/",
      },
    ],
  };
}

export function getPsoriasisSeverityColor(severity: PsoriasisSeverity): string {
  switch (severity) {
    case "mild": return "text-green-700 bg-green-50 border-green-200";
    case "moderate": return "text-amber-700 bg-amber-50 border-amber-200";
    case "severe": return "text-red-700 bg-red-50 border-red-200";
  }
}

export function getPsoriasisSeverityBadge(severity: PsoriasisSeverity): string {
  switch (severity) {
    case "mild": return "Mild Psoriasis";
    case "moderate": return "Moderate Psoriasis";
    case "severe": return "Severe Psoriasis";
  }
}
